CREATE VIEW v_client_district AS SELECT client.client_id, client.gender, client.birth_date, district.district_id, district.A2 AS district_name, district.A3 AS region, district.A4 AS no_of_inhabitants, district.A11 AS avg_salary, client.district_id AS client_district_id, district.A12, district.A13, district.A15 FROM client LEFT JOIN district ON client.district_id = district.district_id;

CREATE VIEW v_account_district AS SELECT account.account_id, account.frequency, account.date AS account_created_date, district.district_id, district.A2 AS district_name, district.A3 AS region, district.A11 AS avg_salary, account.district_id AS account_district_id, district.A4, district.A12, district.A13, district.A15 FROM account LEFT JOIN district ON account.district_id = district.district_id;

CREATE VIEW v_account_loan AS SELECT account.account_id, account.frequency, account.date AS account_date, loan.loan_id, loan.date AS loan_date, loan.amount AS loan_amount, loan.duration AS loan_duration, loan.payments AS loan_payments, loan.status AS loan_status, account.district_id, loan.account_id AS loan_account_id FROM account LEFT JOIN loan ON account.account_id = loan.account_id;

CREATE VIEW v_account_client_disp_district AS SELECT client.client_id, client.gender, client.birth_date, client.district_id, disp.disp_id, disp.client_id AS disp_client_id, disp.account_id, disp.type, account.account_id AS account_account_id, account.district_id AS account_district_id, account.frequency, account.date, district.district_id AS district_district_id, district.A2, district.A3, district.A4, district.A11, district.A12, district.A13, district.A15 FROM client LEFT JOIN disp ON client.client_id = disp.client_id LEFT JOIN account ON disp.account_id = account.account_id LEFT JOIN district ON account.district_id = district.district_id;
